def cancelar_pendentes_duplicados(apps, schema_editor):
    """Antes da regra "um pendente por utilizador": fica só o pendente mais recente."""
    Pagamento = apps.get_model('pagamentos', 'Pagamento')
    vistos = set()
    for p in Pagamento.objects.filter(estado='pendente').order_by('user_id', '-created_at'):
        if p.user_id in vistos:
            p.estado = 'cancelado'
            p.motivo_falha = 'Substituído por um novo pedido de pagamento.'
            p.save(update_fields=['estado', 'motivo_falha'])
        vistos.add(p.user_id)


